```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#98FB98", 30);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Sunset
  brush.fill("#FF4500", 70);
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(400, 350);
  brush.vertex(0, 350);
  brush.endShape(true);
}
```

